const $=(selector,root=document)=>root.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fa=new Intl.NumberFormat('fa-IR'),money=value=>`${fa.format(value)} تومان`;
const date=value=>new Intl.DateTimeFormat('fa-IR',{dateStyle:'medium',timeStyle:'short'}).format(new Date(typeof value==='number'?value*1000:value));
const state=value=>({pending:'در انتظار پرداخت',success:'پرداخت موفق',failed:'ناموفق',open:'منتظر پاسخ',answered:'پاسخ داده شده',closed:'بسته',awaiting_payment:'در انتظار پرداخت',processing:'در حال انجام',delivered:'تحویل شده',canceled:'لغو شده',demo_complete:'تکمیل آزمایشی',refunded:'بازپرداخت به کیف پول',legacy:'قدیمی'}[value]||value);
let me=null,page=1,search='',rows=[],section='',permissionLabels={},supportId=null,supportCursor=0,supportLoading=false;
const can=permission=>me?.owner||me?.permissions.includes(permission);
const sections=[['dashboard','نمای کلی','⌂',['dashboard.read']],['products','محصولات','▦',['products.read','products.create']],['orders','سفارش‌ها','▤',['orders.read']],['customers','کاربران','◉',['customers.read']],['tickets','تیکت‌ها','◌',['tickets.read']],['chat','گفت‌وگوی آنلاین','☷',['chat.read']],['discounts','کدهای تخفیف','％',['discounts.read','discounts.write']],['staff','کارمندان و دسترسی‌ها','♙',[]],['settings','تنظیمات فروشگاه','⚙',['settings.read']],['activations','مدیریت فعال‌سازی','◈',['activations.read']],['audit','گزارش فعالیت‌ها','≡',['audit.read']]];

function toast(message,error=false){const node=document.createElement('div');node.className='toast'+(error?' error':'');node.textContent=message;$('#admin-toasts').append(node);setTimeout(()=>node.remove(),4000);}
async function api(path,options={}){const headers={...options.headers};if(options.body&&!(options.body instanceof Blob))headers['Content-Type']='application/json';if(me?.csrf)headers['X-CSRF-Token']=me.csrf;const response=await fetch('/api/admin'+path,{...options,headers,signal:AbortSignal.timeout(30000)});const data=await response.json().catch(()=>({detail:'پاسخ سرور نامعتبر است.'}));if(!response.ok){if(response.status===401&&path!=='/login'){showLogin();}throw new Error(data.detail||'انجام عملیات ممکن نشد.');}return data;}
function showLogin(){me=null;$('#admin-app').hidden=true;$('#admin-login').hidden=false;$('#admin-modal').close();supportId=null;}
function heading(title,description,action=''){return `<div class="admin-heading"><div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function table(headers,body){return `<div class="data-table-wrapper"><table class="data-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${body||`<tr><td colspan="${headers.length}" class="admin-empty">موردی برای نمایش وجود ندارد.</td></tr>`}</tbody></table></div>`;}
function pagination(more){return `<div class="pagination"><button class="button secondary" data-page="${page-1}" ${page===1?'disabled':''}>قبلی</button><span>صفحه ${fa.format(page)}</span><button class="button secondary" data-page="${page+1}" ${!more?'disabled':''}>بعدی</button></div>`;}
function searchBox(placeholder){return `<form class="admin-search" id="admin-search"><input name="q" value="${esc(search)}" placeholder="${placeholder}" aria-label="جستجو"><button class="button secondary">جستجو</button></form>`;}
function bindList(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=Number(b.dataset.page);render();});$('#admin-search')?.addEventListener('submit',event=>{event.preventDefault();search=event.currentTarget.elements.q.value;page=1;render();});}
function modal(title,html){$('#admin-modal-title').textContent=title;$('#admin-modal-body').innerHTML=html;$('#admin-modal').showModal();}
function closeModal(){$('#admin-modal').close();supportId=null;}
$('#close-admin-modal').onclick=closeModal;$('#admin-modal').addEventListener('close',()=>supportId=null);
async function submitForm(form,action){const button=$('[type="submit"]',form);const label=button?.textContent;if(button){button.disabled=true;button.textContent='در حال ذخیره…';}$('.field-error',form).textContent='';try{await action();}catch(error){$('.field-error',form).textContent=error.message;}finally{if(button){button.disabled=false;button.textContent=label;}}}
function field(name,label,value='',extra=''){return `<label>${label}<input name="${name}" value="${esc(value)}" ${extra}></label>`;}
function area(name,label,value='',extra=''){return `<label>${label}<textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`;}
function select(name,label,options,value){return `<label>${label}<select name="${name}">${options.map(([id,text])=>`<option value="${id}" ${String(value)===String(id)?'selected':''}>${text}</option>`).join('')}</select></label>`;}
function check(name,label,value=false,disabled=false){return `<label class="checkbox-row"><input type="checkbox" name="${name}" ${value?'checked':''} ${disabled?'disabled':''}><span>${label}</span></label>`;}
const formEnd='<p class="field-error" role="alert"></p><div class="form-actions"><button class="button primary" type="submit">ذخیره تغییرات</button><button class="button secondary cancel-modal" type="button">انصراف</button></div></form>';
function bindCancel(){$('.cancel-modal')?.addEventListener('click',closeModal);}

async function init(){me=await api('/me');$('#admin-login').hidden=true;$('#admin-app').hidden=false;$('#staff-display').textContent=me.name+(me.owner?' · مالک':' · کارمند');const permitted=sections.filter(s=>s[0]==='staff'?me.owner:s[3].some(can));$('#admin-navigation').innerHTML=permitted.map(s=>`<a href="#${s[0]}"><span>${s[2]}</span>${s[1]}</a>`).join('');section=(/^(customer|order)\//.test(location.hash.slice(1))||permitted.some(s=>s[0]===location.hash.slice(1)))?location.hash.slice(1):(permitted[0]?.[0]||'none');await render();}
$('#staff-login-form').onsubmit=event=>{event.preventDefault();const form=event.currentTarget;submitForm(form,async()=>{await api('/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});form.reset();await init();});};
$('#admin-logout').onclick=async()=>{try{await api('/logout',{method:'POST'});showLogin();}catch(error){toast(error.message,true);}};
window.addEventListener('hashchange',()=>{section=location.hash.slice(1);page=1;search='';supportId=null;closeModal();render();});

async function render(){if(!me)return;$('#admin-section-title').textContent=sections.find(s=>s[0]===section)?.[1]||'مدیریت';document.querySelectorAll('#admin-navigation a').forEach(a=>a.classList.toggle('active',a.hash==='#'+section));$('#admin-content').innerHTML='<p class="admin-note">در حال دریافت اطلاعات…</p>';
try{if(section==='dashboard')await dashboard();else if(section==='products')await products();else if(section==='orders')await orders();else if(section==='customers')await customers();else if(section==='discounts')await discounts();else if(section==='staff')await staff();else if(section==='settings')await settingsPage();else if(section==='activations')await activationsPage();else if(section.startsWith('customer/'))await customerPage();else if(section.startsWith('order/'))await orderPage();else if(section==='audit')await audit();else if(['tickets','chat'].includes(section))await conversations();else $('#admin-content').innerHTML='<div class="admin-empty">دسترسی فعالی برای این بخش ندارید. از مالک بخواهید مجوز مناسب را تعیین کند.</div>';bindList();}catch(error){$('#admin-content').innerHTML=`<div class="admin-empty"><p>${esc(error.message)}</p><button class="button secondary" id="retry-admin">تلاش دوباره</button></div>`;$('#retry-admin').onclick=render;}}

async function dashboard(){
 const data=await api('/dashboard');const labels={products:'محصولات فروشگاه',orders:'سفارش‌های ثبت‌شده',customers:'حساب‌های مشتری',ticket:'تیکت منتظر پاسخ',chat:'گفت‌وگوی منتظر پاسخ',real_revenue:'درآمد پرداخت واقعی'};
 $('#admin-content').innerHTML=heading('امروز در فروشگاه چه خبر است؟','سفارش‌ها، پشتیبانی و برداشت‌های پیش رو در یک نگاه.')+`<div class="admin-metrics">${Object.entries(data).map(([key,value])=>`<article class="metric"><span>${labels[key]}</span><strong>${key==='real_revenue'?money(value):fa.format(value)}</strong></article>`).join('')}</div>`;
 if(can('activations.read'))$('#admin-content').insertAdjacentHTML('beforeend',await reminderHTML());
}

async function products(){const data=can('products.read')?await api(`/products?page=${page}&q=${encodeURIComponent(search)}`):{items:[],has_more:false};rows=data.items;$('#admin-content').innerHTML=heading('محصولات','پیش‌نویس بسازید، توضیحات و رسانه اضافه کنید و وقتی آماده بود منتشر کنید.',can('products.create')?'<button class="button primary" id="add-product">+ محصول جدید</button>':'')+searchBox('جستجوی نام محصول')+table(['محصول','قیمت','وضعیت','نسخه','عملیات'],rows.map(p=>`<tr><td><strong>${esc(p.title)}</strong><small>${esc(p.period)} · #${p.id}</small></td><td>${money(p.price)}</td><td><span class="state-badge">${p.archived?'بایگانی':!p.published?'پیش‌نویس':p.available?'منتشرشده':'ناموجود'}</span></td><td>${fa.format(p.revision)}</td><td><div class="table-actions">${can('products.update')?`<button data-edit-product="${p.id}">ویرایش</button>`:''}${can('products.archive')?`<button data-archive="${p.id}" class="danger">${p.archived?'بازیابی':'بایگانی'}</button>`:''}${p.published&&!p.archived?`<a href="/product.html?id=${p.id}" target="_blank" rel="noopener">نمایش ↗</a>`:''}</div></td></tr>`).join(''))+pagination(data.has_more);
$('#add-product')?.addEventListener('click',()=>productForm());document.querySelectorAll('[data-edit-product]').forEach(b=>b.onclick=()=>productForm(rows.find(p=>p.id===Number(b.dataset.editProduct))));document.querySelectorAll('[data-archive]').forEach(b=>b.onclick=async()=>{const p=rows.find(p=>p.id===Number(b.dataset.archive));try{await api(`/products/${p.id}/archive`,{method:'POST',body:JSON.stringify({archived:!p.archived})});toast(p.archived?'محصول بازیابی شد.':'محصول بایگانی شد؛ از سایت پنهان می‌شود.');render();}catch(e){toast(e.message,true);}});}

function productForm(p={}){modal(p.id?'ویرایش محصول':'محصول جدید',`<form id="product-form" class="portal-form"><div class="form-grid">${field('title','نام محصول',p.title,'required minlength="2" maxlength="200"')}${field('brand','نام انگلیسی / برند',p.brand,'maxlength="100"')}${select('category','دسته‌بندی',[['ai','هوش مصنوعی'],['vpn','تحریم‌شکن'],['stream','استریم و موسیقی'],['tools','ابزارهای حرفه‌ای']],p.category||'ai')}${select('icon','نشان محصول (اگر تصویر ندارید)',[['gpt','هوش مصنوعی'],['gemini','ستاره'],['spotify','موسیقی'],['nord','اتصال'],['trading','تحلیل'],['adobe','طراحی']],p.icon||'gpt')}${field('price','قیمت فروش — تومان',p.price||'','type="number" min="1000" max="500000000" required')}${field('original_price','قیمت قبل از تخفیف — صفر یعنی بدون تخفیف',p.original_price||0,'type="number" min="0" max="500000000"')}${field('period','دوره اشتراک',p.period||'اشتراک یک‌ماهه','required maxlength="100"')}${field('badge','برچسب کوتاه',p.badge,'maxlength="80"')}<div class="span-2">${area('description','معرفی کوتاه برای کارت محصول',p.description,'required minlength="10" maxlength="500" rows="2"')}</div><div class="span-2">${area('content','توضیحات کامل صفحه محصول',p.content,'maxlength="30000" rows="8"')}<small>متن ساده؛ برای جداکردن بخش‌ها یک خط خالی بگذارید. کد HTML اجرا نمی‌شود.</small></div><div class="span-2">${area('features','ویژگی‌ها — هر مورد در یک خط',(p.features||[]).join('\n'),'rows="3"')}</div></div><section class="form-section"><h3>تصاویر و ویدئوی معرفی</h3>${can('media.upload')?'<div class="media-upload-row"><p>تصویر JPG، PNG یا WebP و ویدئوی MP4؛ حداکثر ۲۵ مگابایت. فایل انتخاب‌شده بارگذاری و به فرم اضافه می‌شود.</p><input type="file" id="product-upload" accept="image/jpeg,image/png,image/webp,video/mp4" aria-label="بارگذاری رسانه محصول"><span class="upload-status" id="upload-status"></span></div>':''}${area('images','آدرس تصاویر — هر لینک مستقیم در یک خط',(p.images||[]).join('\n'),'rows="3" dir="ltr"')}${field('video','آدرس مستقیم ویدئو MP4',p.video,'dir="ltr" maxlength="2048"')}</section><div class="form-grid">${field('sort_order','ترتیب نمایش (عدد کمتر، بالاتر)',p.sort_order||0,'type="number" min="0" max="10000"')}<div>${check('require_credentials','برای هر واحد محصول، نام کاربری و رمز اکانت مشتری دریافت شود',p.require_credentials??false)}${check('available','موجود و قابل خرید',p.available??true)}${check('published','انتشار در سایت',p.published??false,!can('products.publish'))}</div></div><p class="staff-help">ذخیره پیش‌نویس، محصول را عمومی نمی‌کند. بایگانی سوابق سفارش را حذف نمی‌کند.</p>${formEnd}`);bindCancel();
$('#product-upload')?.addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;$('#upload-status').textContent='در حال بارگذاری…';try{if(file.size>25*1024*1024)throw new Error('فایل باید کوچک‌تر از ۲۵ مگابایت باشد.');const result=await api('/media',{method:'POST',headers:{'Content-Type':file.type},body:file});const form=$('#product-form');if(file.type==='video/mp4')form.elements.video.value=result.url;else form.elements.images.value=[form.elements.images.value,result.url].filter(Boolean).join('\n');$('#upload-status').textContent='بارگذاری انجام شد؛ برای اتصال فایل به محصول، فرم را ذخیره کنید.';}catch(e){$('#upload-status').textContent=e.message;}});
$('#product-form').onsubmit=event=>{event.preventDefault();const form=event.currentTarget;submitForm(form,async()=>{const data=Object.fromEntries(new FormData(form));for(const key of ['price','original_price','sort_order'])data[key]=Number(data[key]);data.features=data.features.split('\n').map(s=>s.trim()).filter(Boolean);data.images=data.images.split('\n').map(s=>s.trim()).filter(Boolean);data.require_credentials=form.elements.require_credentials.checked;data.available=form.elements.available.checked;data.published=form.elements.published.checked;data.revision=p.revision||null;await api(p.id?`/products/${p.id}`:'/products',{method:p.id?'PUT':'POST',body:JSON.stringify(data)});closeModal();toast('محصول ذخیره شد.');await render();});};}

async function orders(){const data=await api(`/orders?page=${page}&q=${encodeURIComponent(search)}`);rows=data.items;$('#admin-content').innerHTML=heading('سفارش‌ها','وضعیت پرداخت، پیگیری انجام سفارش و یادداشت‌های مشتری را جدا نگه دارید.')+searchBox('شماره موبایل یا شناسه سفارش')+table(['سفارش / مشتری','مبلغ','پرداخت','انجام سفارش','عملیات'],rows.map(o=>`<tr><td><a href="#customer/${o.user_id}/profile">${esc(o.full_name)}</a><small dir="ltr">${esc(o.mobile)}</small><small dir="ltr">${esc(o.id.slice(0,8))}</small></td><td>${money(o.total_amount)}${o.payment_mode==='demo'?'<small>آزمایشی</small>':''}</td><td>${state(o.status)}</td><td>${state(o.fulfillment)}</td><td><div class="table-actions"><button data-order="${o.id}">جزئیات</button></div></td></tr>`).join(''))+pagination(data.has_more);document.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>location.hash='order/'+b.dataset.order);}
function orderForm(o){modal('جزئیات سفارش',`<div class="order-summary-grid"><div><p>مشتری</p><a href="#customer/${o.user_id}/profile">${esc(o.full_name)}</a><div dir="ltr">${esc(o.mobile)}</div></div><div><p>شناسه سفارش</p><small dir="ltr">${esc(o.id)}</small><p>${date(o.created_at)}</p></div><div><p>مبلغ پرداختی / تخفیف</p>${money(o.total_amount)} / ${money(o.discount_amount)}</div><div><p>وضعیت پرداخت</p>${state(o.status)} ${o.ref_id?`<small dir="ltr">${esc(o.ref_id)}</small>`:''}</div></div>${o.payment_mode==='demo'?'<p class="demo-warning">این سفارش آزمایشی است. تحویل واقعی و تغییر وضعیت پرداخت از پنل مجاز نیست.</p>':''}<ul class="order-lines">${o.items.map(i=>`<li><span>${esc(i.title)} × ${fa.format(i.quantity)}</span><span>${money(i.unit_price*i.quantity)}</span></li>`).join('')}</ul>${can('orders.update')?`<form id="order-form" class="portal-form">${select('fulfillment','وضعیت انجام سفارش',[['awaiting_payment','در انتظار پرداخت'],['processing','در حال انجام'],['delivered','تحویل شده'],['canceled','لغو شده'],['demo_complete','تکمیل آزمایشی']],o.fulfillment)}${area('customer_note','یادداشت قابل مشاهده برای مشتری',o.customer_note,'maxlength="5000" rows="3"')}${area('internal_note','یادداشت داخلی (فقط کارکنان مجاز)',o.internal_note,'maxlength="5000" rows="3"')}${formEnd}`:`<p>${esc(o.customer_note)}</p><p class="admin-note">${esc(o.internal_note||'یادداشت داخلی ثبت نشده است.')}</p>`}`);bindCancel();$('#order-form')?.addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget;submitForm(form,async()=>{await api(`/orders/${o.id}`,{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(form)))});closeModal();toast('جزئیات سفارش ذخیره شد.');render();});});}

async function customers(){const data=await api(`/customers?page=${page}&q=${encodeURIComponent(search)}`);rows=data.items;$('#admin-content').innerHTML=heading('کاربران','حساب‌های تأییدشده با موبایل؛ مسدودسازی، همه نشست‌های کاربر را باطل می‌کند.')+searchBox('نام یا شماره موبایل')+table(['کاربر','موبایل','تلگرام','وضعیت','عملیات'],rows.map(u=>`<tr><td><strong>${esc(u.full_name||'پروفایل تکمیل نشده')}</strong><small>#${u.id}</small></td><td dir="ltr">${esc(u.mobile)}</td><td dir="ltr">${esc(u.telegram_id||'—')}</td><td class="${u.blocked?'user-blocked':''}">${u.blocked?'مسدود':u.registered?'فعال':'ثبت‌نام ناتمام'}</td><td><div class="table-actions"><a href="#customer/${u.id}/profile">جزئیات ↗</a>${can('customers.update')?`<button data-block="${u.id}" class="danger">${u.blocked?'رفع مسدودی':'مسدودسازی'}</button>`:''}</div></td></tr>`).join(''))+pagination(data.has_more);document.querySelectorAll('[data-block]').forEach(b=>b.onclick=async()=>{const user=rows.find(u=>u.id===Number(b.dataset.block));try{await api(`/customers/${user.id}`,{method:'PUT',body:JSON.stringify({blocked:!user.blocked})});toast('وضعیت کاربر تغییر کرد.');render();}catch(e){toast(e.message,true);}});}

async function discounts(){const data=can('discounts.read')?await api(`/discounts?page=${page}`):{items:[],has_more:false};rows=data.items;$('#admin-content').innerHTML=heading('کدهای تخفیف','درصدی یا مبلغ ثابت، با تاریخ اعتبار و محدودیت استفاده.',can('discounts.write')?'<button class="button primary" id="add-discount">+ کد تخفیف جدید</button>':'')+table(['کد','مقدار','حداقل سبد','سقف کل / هر کاربر','وضعیت','عملیات'],rows.map(c=>`<tr><td><strong dir="ltr">${esc(c.code)}</strong></td><td>${c.kind==='percent'?fa.format(c.value)+'٪':money(c.value)}</td><td>${money(c.min_total)}</td><td>${fa.format(c.max_uses)} / ${fa.format(c.per_user)}</td><td>${c.active?'فعال':'غیرفعال'}</td><td><div class="table-actions">${can('discounts.write')?`<button data-discount="${c.id}">ویرایش</button>`:''}</div></td></tr>`).join(''))+pagination(data.has_more);$('#add-discount')?.addEventListener('click',()=>discountForm());document.querySelectorAll('[data-discount]').forEach(b=>b.onclick=()=>discountForm(rows.find(c=>c.id===Number(b.dataset.discount))));}
function localDate(stamp){if(!stamp)return '';const d=new Date(stamp*1000);return new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function discountForm(c={}){modal(c.id?'ویرایش کد تخفیف':'کد تخفیف جدید',`<form id="discount-form" class="portal-form"><div class="form-grid">${field('code','کد انگلیسی تخفیف',c.code,'required pattern="[A-Za-z0-9_-]{3,40}" dir="ltr"')}${select('kind','نوع تخفیف',[['percent','درصدی'],['fixed','مبلغ ثابت — تومان']],c.kind||'percent')}${field('value','مقدار (درصد تا ۹۰، یا مبلغ تومان)',c.value||10,'type="number" required min="1" max="500000000"')}${field('min_total','حداقل مبلغ سبد — تومان',c.min_total||0,'type="number" min="0"')}${field('max_discount','سقف مبلغ تخفیف — صفر بدون سقف',c.max_discount||0,'type="number" min="0"')}${field('max_uses','حداکثر استفاده کل',c.max_uses||100,'type="number" min="1" max="1000000"')}${field('per_user','حداکثر استفاده هر کاربر',c.per_user||1,'type="number" min="1" max="1000"')}${check('active','کد تخفیف فعال باشد',c.active??true)}${field('starts_at','شروع اعتبار — زمان محلی دستگاه',localDate(c.starts_at),'type="datetime-local"')}${field('expires_at','پایان اعتبار — زمان محلی دستگاه',localDate(c.expires_at),'type="datetime-local"')}</div><p class="staff-help">تاریخ خالی یعنی بدون محدودیت آن سمت. استفاده‌های در انتظار پرداخت، تا ۲۰ دقیقه ظرفیت تخفیف را رزرو می‌کنند.</p>${formEnd}`);bindCancel();$('#discount-form').onsubmit=event=>{event.preventDefault();const form=event.currentTarget;submitForm(form,async()=>{const data=Object.fromEntries(new FormData(form));for(const key of ['value','min_total','max_discount','max_uses','per_user'])data[key]=Number(data[key]);for(const key of ['starts_at','expires_at'])data[key]=data[key]?Math.floor(new Date(data[key]).getTime()/1000):0;data.active=form.elements.active.checked;await api(c.id?`/discounts/${c.id}`:'/discounts',{method:c.id?'PUT':'POST',body:JSON.stringify(data)});closeModal();toast('کد تخفیف ذخیره شد.');render();});};}

async function staff(){const data=await api('/staff');rows=data.items;permissionLabels=data.permissions;$('#admin-content').innerHTML=heading('کارمندان و دسترسی‌ها','هر کارمند فقط عملیات انتخاب‌شده را می‌تواند انجام دهد. مدیریت کارکنان مخصوص مالک است.','<button class="button primary" id="add-staff">+ کارمند جدید</button>')+table(['کارمند','نام کاربری','مجوزها','وضعیت','عملیات'],rows.map(s=>`<tr><td><strong>${esc(s.name)}</strong></td><td dir="ltr">${esc(s.username)}</td><td>${s.owner?'مالک · همه دسترسی‌ها':fa.format(s.permissions.length)+' مجوز'}</td><td>${s.active?'فعال':'غیرفعال'}</td><td><div class="table-actions">${!s.owner?`<button data-staff="${s.id}">ویرایش دسترسی</button><button class="danger" data-delete-staff="${s.id}">حذف</button>`:'—'}</div></td></tr>`).join(''))+'<div class="admin-note">ویرایش مجوز، تغییر رمز یا حذف کارمند بلافاصله نشست‌های او را باطل می‌کند. حساب مالک از این صفحه حذف نمی‌شود.</div>';$('#add-staff').onclick=()=>staffForm();document.querySelectorAll('[data-staff]').forEach(b=>b.onclick=()=>staffForm(rows.find(s=>s.id===Number(b.dataset.staff))));document.querySelectorAll('[data-delete-staff]').forEach(b=>b.onclick=()=>deleteStaff(rows.find(s=>s.id===Number(b.dataset.deleteStaff))));}
function staffForm(s={}){const groups={};for(const [key,label] of Object.entries(permissionLabels)){const prefix=key.split('.')[0];(groups[prefix]||=[]).push([key,label]);}modal(s.id?'ویرایش دسترسی کارمند':'ساخت حساب کارمند',`<form id="staff-form" class="portal-form"><div class="form-grid">${field('name','نام نمایشی',s.name,'required minlength="2" maxlength="100"')}${field('username','نام کاربری انگلیسی',s.username,'required pattern="[A-Za-z0-9_.-]{3,50}" dir="ltr"')}${field('password',s.id?'رمز جدید — خالی یعنی بدون تغییر':'رمز اولیه — حداقل ۱۲ کاراکتر','','type="password" autocomplete="new-password" minlength="12" maxlength="128" '+(s.id?'':'required'))}${check('active','حساب فعال باشد',s.active??true)}</div><section class="form-section"><h3>دسترسی‌های جزئی</h3><p class="staff-help">مجوز مشاهده و عملیات را جدا انتخاب کنید. مثلاً کارشناس پشتیبانی به مشاهده تیکت و پاسخ تیکت نیاز دارد.</p><div class="permission-presets"><button type="button" data-preset="support">الگوی پشتیبانی</button><button type="button" data-preset="catalog">الگوی مدیریت محصولات</button><button type="button" data-preset="clear">پاک‌کردن انتخاب‌ها</button></div><div class="permission-grid">${Object.values(groups).map(group=>`<div class="permission-group"><h4>${esc(group[0][1].split(':')[0])}</h4>${group.map(([key,label])=>`<label><input type="checkbox" name="permission" value="${key}" ${(s.permissions||[]).includes(key)?'checked':''}>${esc(label.split(':').slice(1).join(':'))}</label>`).join('')}</div>`).join('')}</div></section>${formEnd}`);bindCancel();document.querySelectorAll('[data-preset]').forEach(button=>button.onclick=()=>{const set=button.dataset.preset==='support'?['dashboard.read','tickets.read','tickets.reply','tickets.manage','chat.read','chat.reply','chat.manage','orders.read','customers.read']:button.dataset.preset==='catalog'?['dashboard.read','products.read','products.create','products.update','products.publish','products.archive','media.upload','sync.read']:[];document.querySelectorAll('[name="permission"]').forEach(box=>box.checked=set.includes(box.value));});$('#staff-form').onsubmit=event=>{event.preventDefault();const form=event.currentTarget;submitForm(form,async()=>{const data={username:form.elements.username.value,name:form.elements.name.value,password:form.elements.password.value||null,permissions:[...form.querySelectorAll('[name="permission"]:checked')].map(b=>b.value),active:form.elements.active.checked};await api(s.id?`/staff/${s.id}`:'/staff',{method:s.id?'PUT':'POST',body:JSON.stringify(data)});closeModal();toast('حساب و دسترسی‌های کارمند ذخیره شد.');render();});};}
function deleteStaff(s){modal('حذف دسترسی کارمند',`<p>دسترسی «${esc(s.name)}» قطع و همه نشست‌های او باطل می‌شود. سوابق فعالیت برای پیگیری باقی می‌مانند.</p><div class="form-actions"><button class="button primary" id="confirm-delete-staff">حذف دسترسی</button><button class="button secondary cancel-modal">انصراف</button></div>`);bindCancel();$('#confirm-delete-staff').onclick=async()=>{try{await api(`/staff/${s.id}`,{method:'DELETE'});closeModal();toast('دسترسی کارمند حذف شد.');render();}catch(e){toast(e.message,true);}};}

async function audit(){const data=await api(`/audit?page=${page}`);$('#admin-content').innerHTML=heading('گزارش فعالیت‌ها','ردیابی عملیات مدیریتی؛ رمزها، کد ورود و متن پیام‌ها در این گزارش ذخیره نمی‌شوند.')+table(['زمان','شناسه کارمند','عملیات','موضوع'],data.items.map(a=>`<tr><td>${date(a.created_at)}</td><td>${a.actor_id||'سیستم'}</td><td dir="ltr">${esc(a.action)}</td><td dir="ltr">${esc(a.target)}</td></tr>`).join(''))+pagination(data.has_more);}

async function conversations(){const kind=section==='chat'?'chat':'ticket';const data=await api(`/conversations?kind=${kind}&page=${page}`);rows=data.items;$('#admin-content').innerHTML=heading(kind==='chat'?'گفت‌وگوی آنلاین':'تیکت‌ها',kind==='chat'?'پیام‌ها هر چند ثانیه تازه می‌شوند؛ آنلاین‌بودن کارشناس با حضور فعال پنل سنجیده می‌شود.':'پاسخ‌گویی، تغییر وضعیت و ارجاع درخواست‌ها به کارمند مناسب.')+table(['موضوع','کاربر','اولویت','وضعیت','آخرین فعالیت','عملیات'],rows.map(c=>`<tr><td><strong>${esc(c.subject)}</strong></td><td>#${c.user_id}</td><td>${c.priority==='high'?'بالا':'عادی'}</td><td><span class="state-badge">${state(c.status)}</span></td><td>${date(c.updated_at)}</td><td><div class="table-actions"><button data-conversation="${c.id}">بازکردن</button></div></td></tr>`).join(''))+pagination(data.has_more);document.querySelectorAll('[data-conversation]').forEach(b=>b.onclick=()=>conversationModal(rows.find(c=>c.id===b.dataset.conversation)));}
async function conversationModal(c){const prefix=c.kind==='chat'?'chat':'tickets';let agents=[];try{if(can(prefix+'.manage'))agents=await api('/support-staff');}catch{}supportId=c.id;supportCursor=0;modal(c.subject,`<p class="staff-help">مشتری #${c.user_id}${c.order_id?' · سفارش '+esc(c.order_id):''} <span id="support-state">${state(c.status)}</span></p><div id="admin-messages" class="messages admin-messages" aria-live="polite"></div>${can(prefix+'.reply')?`<form id="admin-reply-form" class="portal-form">${area('body','پاسخ به مشتری','','required maxlength="5000" rows="3"')}<p class="field-error" role="alert"></p><button class="button primary" type="submit">ارسال پاسخ</button></form>`:''}${can(prefix+'.manage')?`<form id="support-state-form" class="portal-form form-section"><div class="support-selects">${select('status','وضعیت',[['open','باز'],['answered','پاسخ داده شده'],['closed','بسته']],c.status)}${select('assigned_to','ارجاع به',[['','بدون ارجاع'],...agents.filter(a=>a[c.kind==='chat'?'chat':'tickets']).map(a=>[a.id,esc(a.name)])],c.assigned_to||'')}</div><p class="field-error" role="alert"></p><button class="button secondary" type="submit">ثبت وضعیت و ارجاع</button></form>`:''}`);
$('#admin-reply-form')?.addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget;submitForm(form,async()=>{await api(`/conversations/${c.id}/messages`,{method:'POST',body:JSON.stringify({body:form.elements.body.value})});form.reset();await pollSupport();});});$('#support-state-form')?.addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget;submitForm(form,async()=>{await api(`/conversations/${c.id}`,{method:'PUT',body:JSON.stringify({status:form.elements.status.value,assigned_to:form.elements.assigned_to.value?Number(form.elements.assigned_to.value):null})});toast('وضعیت و ارجاع ثبت شد.');await pollSupport();});});await pollSupport();}
async function pollSupport(){if(!supportId||supportLoading||document.hidden)return;const id=supportId;supportLoading=true;try{const data=await api(`/conversations/${id}?after=${supportCursor}`);if(supportId!==id)return;$('#support-state').textContent=state(data.conversation.status);if(data.messages.length){$('#admin-messages').insertAdjacentHTML('beforeend',data.messages.map(m=>`<article class="message ${m.sender==='staff'?'staff-message':'customer-message'}"><small>${m.sender==='staff'?'پشتیبانی':'مشتری'} · ${date(m.created_at)}</small><p>${esc(m.body)}</p></article>`).join(''));supportCursor=data.messages.at(-1).id;$('#admin-messages').scrollTop=$('#admin-messages').scrollHeight;}}catch(e){toast(e.message,true);}finally{supportLoading=false;}}
setInterval(pollSupport,6000);
setInterval(async()=>{if(!me||document.hidden)return;try{me=await api('/me');}catch{}},30000);
init().catch(()=>showLogin());

async function settingsPage(){
 const d=await api('/settings');
 $('#admin-content').innerHTML=heading('تنظیمات فروشگاه','تنظیمات روزمره در گروه‌های مستقل؛ کلیدهای محرمانه فقط روی سرور نگهداری می‌شوند.')+`<form id="settings-form" class="portal-form settings-layout">
 <nav class="settings-nav"><a href="#settings-general">فروشگاه و ارتباطات</a><a href="#settings-support">پشتیبانی و پیام‌ها</a><a href="#settings-wallet">کیف پول</a><a href="#settings-activation">فعال‌سازی و امنیت</a></nav>
 <div class="settings-sections"><section id="settings-general" class="content-panel"><span class="section-kicker">هویت فروشگاه</span><h2>فروشگاه و ارتباطات</h2><div class="form-grid">${field('store_name','نام فروشگاه',d.store_name,'required maxlength="100"')}${field('telegram_url','کانال تلگرام',d.telegram_url,'dir="ltr"')}${field('instagram_url','اینستاگرام',d.instagram_url,'dir="ltr"')}${field('support_url','لینک پشتیبانی تلگرام',d.support_url,'dir="ltr"')}${field('bot_url','لینک ربات',d.bot_url,'dir="ltr"')}${field('support_hours','ساعات پاسخ‌گویی',d.support_hours)}</div>${area('store_notice','اطلاعیه صفحه فروشگاه',d.store_notice,'maxlength="500"')}</section>
 <section id="settings-support" class="content-panel"><span class="section-kicker">ارتباط با مشتری</span><h2>چت، تیکت و ارسال پیام</h2>${check('chat_enabled','گفت‌وگوی آنلاین فعال باشد',d.chat_enabled)}${area('chat_offline_message','متن هنگام قطع چت',d.chat_offline_message,'required maxlength="500"')}${check('ticket_sms_enabled','پس از پاسخ پشتیبان به تیکت، پیامک اطلاع‌رسانی در صف قرار بگیرد',d.ticket_sms_enabled)}${area('ticket_sms_text','متن اطلاع‌رسانی پاسخ تیکت (بدون رمز یا جزئیات خصوصی)',d.ticket_sms_text,'required maxlength="500"')}${check('sms_notifications_enabled','ارسال پیامک اطلاع‌رسانی و پیام دستی فعال باشد',d.sms_notifications_enabled)}${field('sms_sender','شماره فرستنده پیامک (اختیاری)',d.sms_sender,'dir="ltr" pattern="[0-9+]*"')}${check('telegram_messages_enabled','ارسال پیام دستی با ربات فعال باشد',d.telegram_messages_enabled)}<p class="admin-note">ارسال با ربات نیازمند شروع ربات توسط مشتری و ثبت شناسه عددی صحیح اوست. این اتصال هیچ محصول یا سفارش ربات را همگام نمی‌کند.</p></section>
 <section id="settings-wallet" class="content-panel"><span class="section-kicker">اعتبار مشتری</span><h2>کیف پول و شارژ</h2>${check('wallet_enabled','استفاده از کیف پول در پرداخت فعال باشد',d.wallet_enabled)}${check('wallet_topup_enabled','درخواست شارژ مستقیم فعال باشد',d.wallet_topup_enabled)}<div class="form-grid">${field('wallet_min_topup','حداقل شارژ — تومان',d.wallet_min_topup,'type="number" min="1000" max="500000000" required')}${field('wallet_max_topup','حداکثر شارژ — تومان',d.wallet_max_topup,'type="number" min="1000" max="500000000" required')}</div><p class="admin-note">شارژ تا اتصال درگاه واقعی، فقط شبیه‌سازی محلی است. مانده آزمایشی و واقعی جدا نگهداری می‌شوند. خاموش‌کردن کیف پول، تاریخچه یا حق بازپرداخت را حذف نمی‌کند.</p></section>
 <section id="settings-activation" class="content-panel"><span class="section-kicker">عملیات و امنیت</span><h2>فعال‌سازی و اطلاعات اکانت</h2>${field('activation_reminder_days','یادآوری از چند روز قبل از برداشت؟',d.activation_reminder_days,'type="number" min="1" max="90" required')}${area('credential_help','راهنمای دریافت اطلاعات اکانت در سفارش',d.credential_help,'maxlength="500"')}<div class="technical-grid"><div><small>محیط</small><b>${esc(d.technical.environment)}</b></div><div><small>پیامک ورود</small><b>${esc(d.technical.sms_mode)}</b></div><div><small>کلید پیامک</small><b>${d.technical.sms_ready?'تنظیم شده':'تنظیم نشده'}</b></div><div><small>توکن ربات</small><b>${d.technical.telegram_ready?'تنظیم شده':'تنظیم نشده'}</b></div><div><small>پرداخت</small><b>${esc(d.technical.payment_mode)}</b></div><div><small>نشست مشتری</small><b>۴۸ ساعت</b></div></div><p class="admin-note">کلید رمزگذاری، توکن ربات، کلید پیامک، دامنه و اتصال درگاه در فایل محیطی سرور تنظیم می‌شوند. مقدار محرمانه در مرورگر نمایش داده نمی‌شود.</p></section>
 <div class="settings-save"><p class="field-error" role="alert"></p>${can('settings.write')?'<button class="button primary" type="submit">ذخیره تنظیمات فروشگاه</button>':'<p>دسترسی شما فقط مشاهده است.</p>'}</div></div></form>`;
 document.querySelectorAll('.settings-nav a').forEach(a=>a.onclick=e=>{e.preventDefault();document.querySelector(a.getAttribute('href')).scrollIntoView({behavior:'smooth',block:'start'});});
 if(!can('settings.write')){$('#settings-form').querySelectorAll('input,textarea').forEach(e=>e.disabled=true);return;}
 $('#settings-form').onsubmit=e=>{e.preventDefault();const form=e.currentTarget;submitForm(form,async()=>{const data=Object.fromEntries(new FormData(form));for(const k of ['chat_enabled','ticket_sms_enabled','sms_notifications_enabled','telegram_messages_enabled','wallet_enabled','wallet_topup_enabled'])data[k]=form.elements[k].checked;for(const k of ['wallet_min_topup','wallet_max_topup','activation_reminder_days'])data[k]=Number(data[k]);await api('/settings',{method:'PUT',body:JSON.stringify(data)});toast('تنظیمات ذخیره شد.');});};
}

const ledgerLabels={topup:'شارژ',adjustment:'اصلاح / جایزه',purchase:'پرداخت سفارش',refund:'بازپرداخت',release:'آزادسازی سفارش ناموفق'};
function ledgerHTML(d){return `<div class="wallet-hero"><span>موجودی ${d.mode==='demo'?'آزمایشی':''}</span><strong>${money(d.balance)}</strong><small>تراکنش‌ها حذف یا بازنویسی نمی‌شوند.</small></div>`+table(['تاریخ','نوع','مبلغ — تومان','توضیح'],d.items.map(e=>`<tr><td>${date(e.created_at)}</td><td>${ledgerLabels[e.kind]||esc(e.kind)}</td><td class="${e.amount>0?'amount-credit':'amount-debit'}" dir="ltr">${e.amount>0?'+':''}${fa.format(e.amount)}</td><td>${esc(e.note)}</td></tr>`).join(''))+pagination(d.has_more);}
async function customerPage(){
 const [,id,tab='profile']=section.split('/');const u=await api(`/customers/${id}`);
 const tabs=[['profile','پروفایل کاربر',true],['messages','ارسال پیام',can('messages.read')||can('messages.send')],['wallet','کیف پول',can('wallet.read')],['orders','سفارش‌ها',can('orders.read')]].filter(x=>x[2]);
 $('#admin-content').innerHTML=heading(u.full_name||'مشتری',`شماره موبایل: ${u.mobile} · شناسه مشتری: ${u.id}`,'<a href="#customers" class="button secondary">بازگشت به کاربران</a>')+`<nav class="detail-tabs">${tabs.map(([key,label])=>`<a class="${key===tab?'active':''}" href="#customer/${id}/${key}">${label}</a>`).join('')}</nav><section id="customer-detail"></section>`;
 const box=$('#customer-detail');
 if(tab==='profile'){
 box.innerHTML=`<div class="dossier-grid"><article class="content-panel"><h2>اطلاعات مشتری</h2><dl class="profile-facts"><dt>نام و نام خانوادگی</dt><dd>${esc(u.full_name)}</dd><dt>شماره موبایل</dt><dd dir="ltr">${esc(u.mobile)}</dd><dt>تلگرام</dt><dd dir="ltr">${esc(u.telegram_id||'—')}</dd><dt>تاریخ ثبت‌نام</dt><dd>${date(u.created_at)}</dd><dt>وضعیت دسترسی</dt><dd>${u.blocked?'مسدود':'فعال'}</dd></dl>${can('customers.update')?`<button class="button secondary" id="dossier-block">${u.blocked?'رفع مسدودی':'مسدودسازی بر اساس موبایل'}</button>`:''}</article><article class="content-panel"><h2>خلاصه حساب</h2>${u.balance!==null?`<p>کیف پول ${u.wallet_mode==='demo'?'آزمایشی':''}</p><strong class="big-number">${money(u.balance)}</strong>`:''}<div class="technical-grid">${Object.entries(u.stats).map(([k,v])=>`<div><small>${state(k)}</small><b>${fa.format(v)}</b></div>`).join('')}</div></article></div>`;
 $('#dossier-block')?.addEventListener('click',async()=>{try{await api(`/customers/${id}`,{method:'PUT',body:JSON.stringify({blocked:!u.blocked})});await render();}catch(e){toast(e.message,true);}});
 }else if(tab==='wallet'){
 const d=await api(`/customers/${id}/wallet?page=${page}`);box.innerHTML=ledgerHTML(d)+(can('wallet.adjust')?`<form id="wallet-adjust" class="portal-form content-panel"><h2>جایزه یا اصلاح موجودی</h2><p>مبلغ مثبت برای واریز؛ مبلغ منفی برای کسر. دلیل برای پیگیری الزامی است.</p>${field('amount','مبلغ تغییر — تومان','','type="number" required min="-500000000" max="500000000"')}${area('note','دلیل تغییر','','required minlength="3" maxlength="500"')}<p class="field-error"></p><button class="button primary" type="submit">ثبت تراکنش</button></form>`:'');
 const key=crypto.randomUUID();$('#wallet-adjust')?.addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;submitForm(form,async()=>{await api(`/customers/${id}/wallet`,{method:'POST',headers:{'Idempotency-Key':key},body:JSON.stringify({amount:Number(form.elements.amount.value),note:form.elements.note.value})});toast('تراکنش ثبت شد.');await render();});});
 }else if(tab==='orders'){
 const d=await api(`/customers/${id}/orders?page=${page}`);box.innerHTML=table(['سفارش','تاریخ','مبلغ','وضعیت','عملیات'],d.items.map(o=>`<tr><td dir="ltr">${esc(o.id)}</td><td>${date(o.created_at)}</td><td>${money(o.total_amount)}</td><td>${state(o.status)}</td><td><a class="button secondary" href="#order/${o.id}">جزئیات</a></td></tr>`).join(''))+pagination(d.has_more);
 }else if(tab==='messages'){
 box.innerHTML=can('messages.send')?`<div class="dossier-grid"><form id="customer-message" class="portal-form content-panel"><h2>ارسال پیام به مشتری</h2>${check('sms','پیامک به شماره تأییدشده',true)}${check('telegram','پیام از طریق ربات',false)}${area('body','متن پیام','','required maxlength="1000" rows="5"')}<p class="field-error"></p><button class="button primary" type="submit">ثبت در صف ارسال</button></form><form id="customer-contact" class="portal-form content-panel"><h2>مقصد تلگرام</h2><p>مشتری باید ربات را شروع کرده باشد. شناسه عددی را از گفت‌وگوی تأییدشده مشتری بگیرید؛ یوزرنیم قابل استفاده نیست.</p>${field('telegram_chat_id','شناسه عددی مشتری در تلگرام',u.telegram_chat_id,'dir="ltr" pattern="[0-9]{0,20}"')}${check('verified','تطابق شناسه با این مشتری را بررسی کردم',false)}<p class="field-error"></p><button class="button secondary" type="submit">ذخیره مقصد</button></form></div>`:'';
 const key=crypto.randomUUID();$('#customer-message')?.addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget;submitForm(f,async()=>{await api(`/customers/${id}/messages`,{method:'POST',headers:{'Idempotency-Key':key},body:JSON.stringify({body:f.elements.body.value,channels:['sms','telegram'].filter(k=>f.elements[k].checked)})});toast('پیام در صف قرار گرفت؛ نتیجه در تاریخچه نمایش داده می‌شود.');await render();});});
 $('#customer-contact')?.addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget;submitForm(f,async()=>{if(!f.elements.verified.checked)throw Error('ابتدا تطابق شناسه و مشتری را بررسی کنید.');await api(`/customers/${id}/contact`,{method:'PUT',body:JSON.stringify({telegram_chat_id:f.elements.telegram_chat_id.value})});toast('مقصد تلگرام ذخیره شد.');});});
 if(can('messages.read')){const d=await api(`/customers/${id}/messages?page=${page}`);const statuses={pending:'در صف',sending:'در حال ارسال',sent:'ارسال شد',simulated:'آزمایشی؛ ارسال نشده',failed:'ناموفق',unknown:'نیازمند بررسی نتیجه',disabled:'ارسال غیرفعال'};box.insertAdjacentHTML('beforeend','<h2>تاریخچه پیام‌ها</h2>'+table(['تاریخ','کانال','متن','نتیجه'],d.items.map(m=>`<tr><td>${date(m.created_at)}</td><td>${m.channel==='sms'?'پیامک':'تلگرام'}</td><td class="message-cell">${esc(m.body)}</td><td>${statuses[m.status]||esc(m.status)}<small>${esc(m.error)}</small></td></tr>`).join(''))+pagination(d.has_more));}
 }
}
async function orderPage(){
 const id=section.slice(6),o=await api('/orders/'+encodeURIComponent(id));
 $('#admin-content').innerHTML=heading('جزئیات سفارش',o.id,'<a class="button secondary" href="#orders">همه سفارش‌ها</a>')+`<div class="content-panel"><a class="customer-link" href="#customer/${o.user_id}/profile">◉ ${esc(o.full_name)} ← پرونده مشتری</a><p dir="ltr">${esc(o.mobile)}</p><div class="technical-grid"><div><small>کل سفارش</small><b>${money(o.total_amount)}</b></div><div><small>از کیف پول</small><b>${money(o.wallet_used)}</b></div><div><small>از درگاه</small><b>${money(o.payable)}</b></div><div><small>وضعیت</small><b>${o.refunded?'بازپرداخت به کیف پول':state(o.fulfillment)}</b></div></div><p>${date(o.created_at)} · ${state(o.status)} ${o.payment_mode==='demo'?'· آزمایشی':''}</p><ul class="order-lines">${o.items.map(i=>`<li>${esc(i.title)} × ${fa.format(i.quantity)} <b>${money(i.unit_price*i.quantity)}</b></li>`).join('')}</ul><p>${esc(o.customer_note||'')}</p><p class="admin-note">${esc(o.internal_note||'')}</p><div class="form-actions">${can('orders.update')&&!o.refunded?'<button class="button secondary" id="edit-detailed-order">ویرایش وضعیت و یادداشت</button>':''}${can('orders.secrets')&&o.has_credentials?'<button class="button secondary" id="reveal-order">نمایش اطلاعات اکانت‌ها</button>':''}${can('wallet.refund')&&o.status==='success'&&!o.refunded?'<button class="button primary" id="refund-order">بازپرداخت کامل به کیف پول</button>':''}</div><div id="order-secrets"></div></div>`;
 $('#edit-detailed-order')?.addEventListener('click',()=>orderForm(o));
 $('#reveal-order')?.addEventListener('click',async()=>{try{const d=await api(`/orders/${id}/credentials`,{method:'POST'});$('#order-secrets').innerHTML='<p class="admin-note">مشاهده اطلاعات ثبت شد. اطلاعات پس از یک دقیقه از صفحه پنهان می‌شود.</p>'+table(['محصول','نام کاربری','رمز'],d.items.map(x=>`<tr><td>${esc(o.items.find(i=>i.product_id===x.product_id)?.title||x.product_id)}</td><td dir="ltr">${esc(x.username)}</td><td dir="ltr">${esc(x.password)}</td></tr>`).join(''));setTimeout(()=>{if($('#order-secrets'))$('#order-secrets').textContent='';},60000);}catch(e){toast(e.message,true);}});
 $('#refund-order')?.addEventListener('click',()=>{modal('بازپرداخت به کیف پول',`<p>مبلغ ${money(o.total_amount)} به کیف پول ${o.payment_mode==='demo'?'آزمایشی':''} مشتری برمی‌گردد. این عملیات فقط یک بار برای این سفارش ثبت می‌شود.</p><form id="refund-form" class="portal-form">${area('note','دلیل بازپرداخت','','required minlength="3" maxlength="500"')}${formEnd}`);bindCancel();$('#refund-form').onsubmit=e=>{e.preventDefault();const f=e.currentTarget;submitForm(f,async()=>{await api(`/orders/${id}/refund`,{method:'POST',body:JSON.stringify({note:f.elements.note.value})});closeModal();toast('بازپرداخت ثبت شد.');await render();});};});
}

async function reminderHTML(){const d=await api('/activation-reminders');return `<section class="content-panel renewal-panel"><div class="card-heading"><div><span class="section-kicker">پیگیری برداشت خودکار</span><h2>برداشت‌های نزدیک و عقب‌افتاده</h2></div><span class="state-badge">${fa.format(d.count)} مورد</span></div><p>بازه یادآوری: ${fa.format(d.days)} روز آینده؛ موارد عقب‌افتاده تا اصلاح تاریخ نمایش داده می‌شوند.</p>${d.items.length?table(['سرویس / اکانت','مشتری','کارت','برداشت بعدی'],d.items.map(a=>`<tr><td>${esc(a.service)}<small dir="ltr">${esc(a.email)}</small></td><td><a href="#customer/${a.user_id}/profile">${esc(a.full_name)}</a></td><td>${esc(a.card_label)} · ${esc(a.last_four)}</td><td class="${a.renewal_at*1000<Date.now()?'amount-debit':''}">${date(a.renewal_at)}</td></tr>`).join('')):'<div class="admin-empty">برداشتی در بازه یادآوری ندارید.</div>'}</section>`;}
async function activationsPage(){
 const d=await api(`/activations?page=${page}&q=${encodeURIComponent(search)}`);
 $('#admin-content').innerHTML=heading('مدیریت فعال‌سازی','ردیابی کارت، اکانت و مشتری؛ از اولین پرداخت تا برداشت بعدی.',`<div class="form-actions"><button class="button secondary" id="manage-cards">کارت‌های من</button>${can('activations.write')?'<button class="button primary" id="new-activation">+ ثبت فعال‌سازی</button>':''}</div>`)+await reminderHTML()+searchBox('شماره کامل / چهار رقم کارت، ایمیل، موبایل، سفارش یا سرویس')+table(['سرویس / اکانت','مشتری','کارت','پرداخت / تمدید','عملیات'],d.items.map(a=>`<tr><td><strong>${esc(a.service)}</strong><small dir="ltr">${esc(a.email)}</small><small>${a.active?'فعال':'بایگانی'}</small></td><td><a href="#customer/${a.user_id}/profile">${esc(a.full_name)}</a><small dir="ltr">${esc(a.mobile)}</small>${a.order_id?`<a href="#order/${a.order_id}">سفارش ↗</a>`:''}</td><td>${esc(a.card_label)}<small dir="ltr">•••• ${esc(a.last_four)}</small></td><td>${date(a.paid_at)}<small>${a.auto_renew?date(a.renewal_at):'برداشت خودکار ندارد'}</small></td><td><div class="table-actions">${can('activations.write')?`<button data-activation="${a.id}">جزئیات / ویرایش</button>`:`<span>${esc(a.account)}</span><small>${esc(a.note)}</small>`}${can('activations.secrets')?`<button data-reveal-activation="${a.id}">رمز اکانت</button>`:''}</div></td></tr>`).join(''))+pagination(d.has_more);
 $('#manage-cards').onclick=()=>cardsModal();$('#new-activation')?.addEventListener('click',()=>activationForm());document.querySelectorAll('[data-activation]').forEach(b=>b.onclick=()=>activationForm(d.items.find(a=>a.id===Number(b.dataset.activation))));document.querySelectorAll('[data-reveal-activation]').forEach(b=>b.onclick=()=>revealSecret(`/activations/${b.dataset.revealActivation}/reveal`,'رمز اکانت','password'));
}
async function revealSecret(path,title,key){try{const d=await api(path,{method:'POST'});modal(title,`<p class="admin-note">این مشاهده در گزارش فعالیت ثبت شد. اطلاعات پس از یک دقیقه پنهان می‌شود.</p><p dir="ltr" class="secret-value">${esc(d[key]||'ثبت نشده')}</p>`);setTimeout(()=>{const node=$('.secret-value');if(node)node.textContent='اطلاعات پنهان شد.';},60000);}catch(e){toast(e.message,true);}}
async function cardsModal(q='',cardPage=1){
 const d=await api(`/activation-cards?q=${encodeURIComponent(q)}&page=${cardPage}`);modal('کارت‌های فعال‌سازی',`<form id="card-search" class="admin-search"><input name="q" value="${esc(q)}" placeholder="نام یا شماره کارت"><button class="button secondary">جستجو</button></form>${can('activations.write')?'<button class="button primary" id="new-card">+ کارت جدید</button>':''}`+table(['کارت','نوع / وضعیت','شماره','عملیات'],d.items.map(c=>`<tr><td>${esc(c.label)}<small>${esc(c.note)}</small></td><td>${c.kind==='single_use'?'یک‌بارمصرف':'قابل شارژ'} · ${c.active?'فعال':'بایگانی'}</td><td dir="ltr">•••• ${esc(c.last_four)}</td><td><div class="table-actions">${can('activations.write')?`<button data-card="${c.id}">ویرایش</button>`:''}${can('activations.secrets')?`<button data-card-reveal="${c.id}">شماره کامل</button>`:''}</div></td></tr>`).join(''))+`<div class="pagination"><button id="cards-prev" class="button secondary" ${cardPage===1?'disabled':''}>قبلی</button><span>${fa.format(cardPage)}</span><button id="cards-next" class="button secondary" ${d.has_more?'':'disabled'}>بعدی</button></div>`);
 $('#card-search').onsubmit=e=>{e.preventDefault();cardsModal(e.currentTarget.elements.q.value);};$('#cards-prev').onclick=()=>cardsModal(q,cardPage-1);$('#cards-next').onclick=()=>cardsModal(q,cardPage+1);$('#new-card')?.addEventListener('click',()=>cardForm());document.querySelectorAll('[data-card]').forEach(b=>b.onclick=()=>cardForm(d.items.find(c=>c.id===Number(b.dataset.card))));document.querySelectorAll('[data-card-reveal]').forEach(b=>b.onclick=()=>revealSecret(`/activation-cards/${b.dataset.cardReveal}/reveal`,'شماره کارت','number'));
}
function cardForm(c={}){modal(c.id?'ویرایش کارت':'کارت جدید',`<form id="card-form" class="portal-form">${field('label','نام قابل تشخیص کارت',c.label,'required minlength="2" maxlength="100"')}${select('kind','نوع کارت',[['single_use','یک‌بارمصرف'],['reloadable','قابل شارژ']],c.kind||'single_use')}${field('number',c.id?'شماره جدید (خالی = بدون تغییر)':'شماره کارت','','dir="ltr" inputmode="numeric" autocomplete="off" maxlength="23" '+(c.id?'':'required'))}<p class="admin-note">شماره کارت رمزگذاری می‌شود. CVV و رمز بانکی را در هیچ فیلدی ننویسید.</p>${area('note','یادداشت غیرمحرمانه',c.note,'maxlength="1000"')}${check('active','کارت فعال باشد',c.active??true)}${formEnd}`);bindCancel();$('#card-form').onsubmit=e=>{e.preventDefault();const f=e.currentTarget;submitForm(f,async()=>{const data=Object.fromEntries(new FormData(f));data.active=f.elements.active.checked;data.revision=c.revision||null;await api(c.id?`/activation-cards/${c.id}`:'/activation-cards',{method:c.id?'PUT':'POST',body:JSON.stringify(data)});toast('کارت ذخیره شد.');await cardsModal();});};}
async function activationForm(a={}){
 modal(a.id?'ویرایش فعال‌سازی':'ثبت فعال‌سازی',`<form id="activation-form" class="portal-form"><div class="form-grid">${field('card_search','پیداکردن کارت (نام یا شماره)','','autocomplete="off"')}<button type="button" class="button secondary" id="lookup-card">جستجوی کارت</button>${select('card_id','کارت استفاده‌شده',a.card_id?[[a.card_id,esc(a.card_label)+' · '+a.last_four]]:[],a.card_id)}${field('customer_search','پیداکردن مشتری (موبایل یا نام)','','autocomplete="off"')}<button type="button" class="button secondary" id="lookup-customer">جستجوی مشتری</button>${select('user_id','مشتری',a.user_id?[[a.user_id,esc(a.full_name)+' · '+a.mobile]]:[],a.user_id)}${field('order_id','شناسه سفارش (اختیاری)',a.order_id,'dir="ltr" maxlength="36"')}${field('service','نام سرویس',a.service,'required minlength="2" maxlength="150"')}${field('email','ایمیل اکانت',a.email,'required dir="ltr" maxlength="254"')}${field('account','مشخصات / نام کاربری اکانت',a.account,'maxlength="200"')}${field('password',a.id?'رمز جدید (خالی = بدون تغییر)':'رمز اکانت','','type="password" autocomplete="new-password" maxlength="256"')}${field('paid_at','تاریخ پرداخت — زمان محلی',localDate(a.paid_at||Date.now()/1000),'type="datetime-local" required')}${check('auto_renew','برداشت خودکار دارد',a.auto_renew??false)}${field('renewal_at','تاریخ برداشت بعدی — زمان محلی',localDate(a.renewal_at),'type="datetime-local"')}${check('active','این فعال‌سازی در پیگیری‌ها فعال باشد',a.active??true)}</div>${area('note','یادداشت پیگیری',a.note,'maxlength="3000" rows="3"')}${formEnd}`);bindCancel();
 const f=$('#activation-form');
 $('#lookup-card').onclick=async()=>{try{const d=await api('/activation-cards?q='+encodeURIComponent(f.elements.card_search.value));f.elements.card_id.innerHTML=d.items.filter(c=>c.active).map(c=>`<option value="${c.id}">${esc(c.label)} · ${esc(c.last_four)}</option>`).join('');if(!d.items.length)toast('کارتی پیدا نشد.',true);}catch(e){toast(e.message,true);}};
 $('#lookup-customer').onclick=async()=>{try{const d=await api('/customers?q='+encodeURIComponent(f.elements.customer_search.value));f.elements.user_id.innerHTML=d.items.map(u=>`<option value="${u.id}">${esc(u.full_name)} · ${esc(u.mobile)}</option>`).join('');if(!d.items.length)toast('مشتری پیدا نشد.',true);}catch(e){toast(e.message,true);}};
 f.onsubmit=e=>{e.preventDefault();submitForm(f,async()=>{const data=Object.fromEntries(new FormData(f));delete data.card_search;delete data.customer_search;data.card_id=Number(data.card_id);data.user_id=Number(data.user_id);data.order_id ||=null;data.paid_at=Math.floor(new Date(data.paid_at).getTime()/1000);data.renewal_at=data.renewal_at?Math.floor(new Date(data.renewal_at).getTime()/1000):0;data.auto_renew=f.elements.auto_renew.checked;data.active=f.elements.active.checked;data.revision=a.revision||null;await api(a.id?`/activations/${a.id}`:'/activations',{method:a.id?'PUT':'POST',body:JSON.stringify(data)});closeModal();toast('فعال‌سازی ذخیره شد.');await render();});};
}
